#pragma once

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <limits>
#include <ostream>
#include <type_traits>
#include <vector>

#include <gtest/gtest.h>

#include <Eigen/Core>

namespace Sophus {
namespace reference {

/// An input of a function and its expected output, both flattened in
/// row-major order. The reference_*.hpp headers generated by
/// sympy/sophus/reference.py hold these cases.
struct Case {
  std::vector<long double> input;
  std::vector<long double> output;
};

inline std::ostream& operator<<(std::ostream& os, Case const& c) {
  os << "input [";
  char const* separator = "";
  for (long double const value : c.input) {
    os << separator << static_cast<double>(value);
    separator = ", ";
  }
  return os << ']';
}

/// The maximum error of an accurate result in units of the machine epsilon
/// of its scalar type.
constexpr long double kMaxErrorInEpsilons = 16;

/// The fraction of the largest magnitude of an output below which the error
/// of a component is measured relative to that fraction instead of the
/// magnitude of the component itself. Rounding in the cancellations of small
/// components of the Jacobians reaches up to a tenth of the largest
/// magnitude, which this fraction leaves room for.
constexpr long double kSmallComponentFraction = 0.25L;

/// Returns the input of a case as a scalar or a column vector.
template <class Tangent>
Tangent input(Case const& c) {
  if constexpr (std::is_arithmetic_v<Tangent>) {
    return static_cast<Tangent>(c.input.front());
  } else {
    Tangent result;
    for (Eigen::Index i = 0; i < result.size(); ++i) {
      result[i] = static_cast<typename Tangent::Scalar>(
          c.input[static_cast<std::size_t>(i)]);
    }
    return result;
  }
}

/**
 * Returns the largest error of the components of `actual`, read in row-major
 * order, relative to `expected`. Each difference is divided by the magnitude
 * of its expected component, but by no less than `kSmallComponentFraction`
 * of the largest magnitude of `expected`, or of one if all expected values
 * vanish. Small components thus need more than the absolute accuracy of the
 * largest one.
 */
template <class Derived>
long double relativeError(Eigen::MatrixBase<Derived> const& actual,
                          std::vector<long double> const& expected) {
  if (static_cast<std::size_t>(actual.size()) != expected.size()) {
    return std::numeric_limits<long double>::infinity();
  }
  long double magnitude = 0;
  for (long double const reference : expected) {
    magnitude = std::max(magnitude, std::abs(reference));
  }
  long double const floor =
      kSmallComponentFraction * (magnitude > 0 ? magnitude : 1);
  long double error = 0;
  std::size_t index = 0;
  for (Eigen::Index row = 0; row < actual.rows(); ++row) {
    for (Eigen::Index col = 0; col < actual.cols(); ++col) {
      long double const value = actual(row, col);
      long double const reference = expected[index];
      ++index;
      long double const component =
          std::abs(value - reference) / std::max(std::abs(reference), floor);
      // Written such that NaN propagates into the result.
      error = std::isnan(value) ? value : component > error ? component : error;
    }
  }
  return error;
}

/// The largest relative error `relativeError` accepts for results of type
/// `Scalar`.
template <class Scalar>
constexpr long double tolerance() {
  return kMaxErrorInEpsilons * std::numeric_limits<Scalar>::epsilon();
}

/// Returns a scalar as a 1x1 matrix and an Eigen expression as a matrix.
template <class T>
auto asMatrix(T const& value) {
  if constexpr (std::is_arithmetic_v<T>) {
    return Eigen::Matrix<T, 1, 1>::Constant(value).eval();
  } else {
    return value.eval();
  }
}

/// Expects `function` to reproduce the output of every case within the
/// tolerance of `Scalar`.
template <class Scalar, class Function>
void expectAccurate(std::vector<Case> const& cases, Function const& function) {
  for (Case const& c : cases) {
    SCOPED_TRACE(::testing::PrintToString(c));
    EXPECT_LE(relativeError(asMatrix(function(c)), c.output),
              tolerance<Scalar>());
  }
}

/// Expect the exp, Dx_exp_x and log of a group to reproduce the reference.
template <class Group>
void expectAccurateExp(std::vector<Case> const& cases) {
  expectAccurate<typename Group::Scalar>(cases, [](Case const& c) {
    return Group::exp(input<typename Group::Tangent>(c)).params();
  });
}

template <class Group>
void expectAccurateDxExpX(std::vector<Case> const& cases) {
  expectAccurate<typename Group::Scalar>(cases, [](Case const& c) {
    return Group::Dx_exp_x(input<typename Group::Tangent>(c));
  });
}

template <class Group>
void expectAccurateLog(std::vector<Case> const& cases) {
  expectAccurate<typename Group::Scalar>(cases, [](Case const& c) {
    using Scalar = typename Group::Scalar;
    auto const params =
        input<Eigen::Matrix<Scalar, Group::num_parameters, 1>>(c);
    return Eigen::Map<Group const>(params.data()).log();
  });
}

}  // namespace reference
}  // namespace Sophus
